+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            background: rgba(15, 23, 42, 0.8);
+            backdrop-filter: blur(20px);
+            font-family: 'Inter', sans-serif;
+        }
+        .game-container {
+            max-width: 600px;
+            padding: 28px;
+            border-radius: 20px;
+            margin: 40px auto;
+            background: rgba(15, 23, 42, 0.8);
+            backdrop-filter: blur(20px);
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.35);
+        }
+        .game-canvas {
+            width: 100%;
+            height: 400px;
+            border: 1px solid #fff;
+        }
+        .hud {
+            display: flex;
+            justify-content: space-between;
+            padding: 10px;
+        }
+        .score {
+            font-size: 24px;
+            font-weight: bold;
+            color: #fff;
+        }
+        .high-score {
+            font-size: 18px;
+            color: #fff;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <div class="hud">
+            <span class="score">Score: <span id="score">0</span></span>
+            <span class="high-score">High Score: <span id="high-score">0</span></span>
+        </div>
+        <canvas class="game-canvas" id="game-canvas" width="400" height="400"></canvas>
+        <div class="game-over" id="game-over" style="display: none;">
+            <h2>Game Over!</h2>
+            <button id="replay-button">Replay</button>
+        </div>
+    </div>
+    <script>
+        const canvas = document.getElementById('game-canvas');
+        const ctx = canvas.getContext('2d');
+        const scoreElement = document.getElementById('score');
+        const highScoreElement = document.getElementById('high-score');
+        const gameOverElement = document.getElementById('game-over');
+        const replayButton = document.getElementById('replay-button');
+        let score = 0;
+        let highScore = localStorage.getItem('highScore') || 0;
+        let snake = [
+            { x: 200, y: 200 },
+            { x: 190, y: 200 },
+            { x: 180, y: 200 }
+        ];
+        let direction = 'right';
+        let food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+        let intervalId;
+        function drawSnake() {
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            snake.forEach((segment, index) => {
+                ctx.fillStyle = index === 0 ? 'rgba(56, 189, 248, 1)' : 'rgba(56, 189, 248, 0.5)';
+                ctx.fillRect(segment.x, segment.y, 10, 10);
+            });
+            ctx.fillStyle = 'rgba(255, 0, 0, 1)';
+            ctx.fillRect(food.x, food.y, 10, 10);
+        }
+        function updateSnake() {
+            const head = snake[0];
+            let newHead;
+            switch (direction) {
+                case 'right':
+                    newHead = { x: head.x + 10, y: head.y };
+                    break;
+                case 'left':
+                    newHead = { x: head.x - 10, y: head.y };
+                    break;
+                case 'up':
+                    newHead = { x: head.x, y: head.y - 10 };
+                    break;
+                case 'down':
+                    newHead = { x: head.x, y: head.y + 10 };
+                    break;
+            }
+            snake.unshift(newHead);
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                score++;
+                scoreElement.textContent = score;
+                food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            } else {
+                snake.pop();
+            }
+            if (snake[0].x < 0 || snake[0].x >= canvas.width || snake[0].y < 0 || snake[0].y >= canvas.height || snake.slice(1).some((segment) => segment.x === snake[0].x && segment.y === snake[0].y)) {
+                clearInterval(intervalId);
+                gameOverElement.style.display = 'block';
+                if (score > highScore) {
+                    highScore = score;
+                    localStorage.setItem('highScore', highScore);
+                    highScoreElement.textContent = highScore;
+                }
+            }
+        }
+        function startGame() {
+            intervalId = setInterval(() => {
+                updateSnake();
+                drawSnake();
+            }, 100);
+        }
+        document.addEventListener('keydown', (event) => {
+            switch (event.key) {
+                case 'ArrowUp':
+                    if (direction !== 'down') direction = 'up';
+                    break;
+                case 'ArrowDown':
+                    if (direction !== 'up') direction = 'down';
+                    break;
+                case 'ArrowLeft':
+                    if (direction !== 'right') direction = 'left';
+                    break;
+                case 'ArrowRight':
+                    if (direction !== 'left') direction = 'right';
+                    break;
+            }
+        });
+        replayButton.addEventListener('click', () => {
+            score = 0;
+            scoreElement.textContent = score;
+            snake = [
+                { x: 200, y: 200 },
+                { x: 190, y: 200 },
+                { x: 180, y: 200 }
+            ];
+            direction = 'right';
+            food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            gameOverElement.style.display = 'none';
+            startGame();
+        });
+        startGame();
+    </script>
+</body>
+</html>

